begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table period_plan_fixture(plan uuid,source uuid,mark uuid,result uuid);grant select,insert,update on period_plan_fixture to cuevo_api;
insert into app.terms(school_id,id,academic_year_id,name,starts_on,ends_on)values('10000000-0000-4000-8000-000000000001','af100000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','School review term','2026-10-01','2026-12-31');
insert into app.report_periods(school_id,id,term_id,name,starts_on,ends_on,created_by)values('10000000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001','af100000-0000-4000-8000-000000000001','School October review','2026-10-01','2026-10-31','20000000-0000-4000-8000-000000000001');
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','af120000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','School planned course','Synthetic','PUBLISHED');
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001','af130000-0000-4000-8000-000000000001','af120000-0000-4000-8000-000000000001','School unit',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001','af140000-0000-4000-8000-000000000001','af130000-0000-4000-8000-000000000001','School explanation lesson',1,'School-authored content');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)values('10000000-0000-4000-8000-000000000001','af150000-0000-4000-8000-000000000001','af120000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','School period assessment','School task',10,'61000000-0000-4000-8000-000000000001',2);
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select is(internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)->>'planStatus','NOT_ESTABLISHED','No declared plan remains unknown');
insert into period_plan_fixture(plan)select(internal.record_objective_plan('plan.create','af120000-0000-4000-8000-000000000001','{"referenceId":"61000000-0000-4000-8000-000000000001","periodId":"af110000-0000-4000-8000-000000000001","expectedPeriodRevision":1,"reason":"Declared school objective period","confirmPlanning":true}','period-plan-create',repeat('a',64),'period-plan')->>'id')::uuid;
select is(internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)->>'plannedTotal','1','One explicit planned denominator');
select throws_ok($$select internal.record_objective_plan('taught.create',(select plan from period_plan_fixture),'{"lessonId":"af140000-0000-4000-8000-000000000001","taughtOn":"2026-09-30","expectedPeriodRevision":1,"note":"Outside selected period","confirmTeaching":true}','period-taught-outside',repeat('b',64),'period-plan')$$,'22023',null,'Taught date outside the declared period denied');
select throws_ok($$select internal.record_objective_plan('taught.create',(select plan from period_plan_fixture),jsonb_build_object('lessonId','af140000-0000-4000-8000-000000000001','taughtOn',((clock_timestamp()at time zone'UTC')::date+1)::text,'expectedPeriodRevision',1,'note','Future lesson cannot be already taught','confirmTeaching',true),'period-taught-future',repeat('b',64),'period-plan')$$,'22023',null,'Future taught declaration denied');
select lives_ok($$select internal.record_objective_plan('taught.create',(select plan from period_plan_fixture),'{"lessonId":"af140000-0000-4000-8000-000000000001","taughtOn":"2026-10-02","expectedPeriodRevision":1,"note":"Teacher explicitly taught this lesson","confirmTeaching":true}','period-taught',repeat('c',64),'period-plan')$$,'Teacher records actual owned course lesson');
select lives_ok($$select internal.record_objective_plan('assessment.create',(select plan from period_plan_fixture),'{"assessmentId":"af150000-0000-4000-8000-000000000001","expectedPolicyVersion":2,"expectedPeriodRevision":1,"reason":"Explicit period inclusion","confirmInclusion":true}','period-assessment',repeat('d',64),'period-plan')$$,'Exact objective task explicitly included');
select is(internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)->'items'->0->>'evidenceCount','0','Task inclusion does not invent learner evidence');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);update period_plan_fixture set source=internal.create_learning_submission('af150000-0000-4000-8000-000000000001','School exact source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);update period_plan_fixture set mark=internal.mark_submission(source,0,'Explicit zero evidence',2,0,true);update period_plan_fixture set result=internal.release_marking(mark,1,false);
select is(internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)->'items'->0->>'evidenceCount','1','One current native evidence source is counted');
select is(internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)->'items'->0->'evidence'->0->'nativeResult'->>'score','0','Explicit native zero is retained');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000005',true);
select throws_ok($$select internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)$$,'42501',null,'Other teacher course coverage denied');
reset role;
select throws_ok($$update app.course_objective_plans set reason='Overwrite'where id=(select plan from period_plan_fixture)$$,'55000',null,'Declared plan immutable');
select throws_ok($$update app.assessments set policy_version=3 where id='af150000-0000-4000-8000-000000000001'$$,'55000',null,'Included assessment objective/policy cannot drift');
select ok(not has_table_privilege('cuevo_api','app.course_objective_plans','SELECT')and not has_function_privilege('authenticated','internal.read_period_objective_coverage(uuid,uuid,integer,uuid)','EXECUTE'),'Private planning records and reads not exposed to browser');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select internal.maintain_school_record('af110000-0000-4000-8000-000000000001','{"resource":"report-periods","expectedRevision":1,"reason":"Changed school window","confirmChange":true,"record":{"termId":"af100000-0000-4000-8000-000000000001","name":"Reviewed October window","startsOn":"2026-10-01","endsOn":"2026-11-15","parentVisible":false}}',false,'period-change',repeat('a',64),'period-plan');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select is(internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)->>'planStatus','REQUIRES_REVIEW','Changed period preserves previous plan with review state');
select lives_ok($$select internal.record_objective_plan('plan.revalidate',(select plan from period_plan_fixture),'{"expectedPeriodRevision":2,"reason":"Reviewed replan for current dates","confirmPlanning":true}','period-replan',repeat('b',64),'period-plan')$$,'Explicit replan creates a new immutable period snapshot');
select lives_ok($$select internal.record_objective_plan('plan.revalidate',(select plan from period_plan_fixture),'{"expectedPeriodRevision":2,"reason":"Reviewed replan for current dates","confirmPlanning":true}','period-replan',repeat('b',64),'period-plan')$$,'Reviewed replan original-key replay is exact');
select is(internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)->>'plannedTotal','1','Replan keeps one current objective denominator');
select is(internal.read_period_objective_coverage('af120000-0000-4000-8000-000000000001','af110000-0000-4000-8000-000000000001',25,null)->'items'->0->>'taughtCount','0','New plan does not infer prior taught sources into a changed period');
reset role;
select*from finish();rollback;
